class Solution {
public:

    bool Manhattan(int x1,int x2,int y1,int y2,int r){
        // Use Euclidean distance squared to avoid floating point issues
        // Formula: (x2-x1)^2 + (y2-y1)^2 <= r^2
        long long dist = (long long)(x2 - x1) * (x2 - x1) + (long long)(y2 - y1) * (y2 - y1);

        if(dist <= (long long)r * r) return true;
        return false;
    }
    vector<int> countPoints(vector<vector<int>>& points, vector<vector<int>>& queries) {
        vector<int> ans;

        for( auto c: queries){
            int x1=c[0];
